// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        vm.prank(address(this));
        c.initialize();
        c.updateAlloSettings(address(0x1234));
        c.updateRoundImplementation(payable(address(0x5678)));

        c.updateRoundImplementation(payable(address(0x1111)));
        address oldVal = c.roundImplementation();
        bool ok;
        try c.updateRoundImplementation(payable(address(0))) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "updateRoundImplementation(0) should revert on reference");
        c.updateRoundImplementation(payable(address(0x2222)));
        bool success;
        try c.updateRoundImplementation(payable(address(0))) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(c.roundImplementation() == address(0x2222), "roundImplementation should remain 0x2222 after attempt to set to zero");
    }
}
